def foot(lang, frm):
    return '<footer><span>%s</span>%s</footer>\n</div>\n<script src="%s" defer></script>\n</body>\n</html>\n' % (T[lang]['foot'], socials('fsoc'), asset(frm, 'app.js'))

def home(lang):
    L = T[lang]; frm = pdir(lang)
    out = head(lang, None, L['home_t'], L['home_d']) + nav(lang, None) + '<main id="main">\n<header class="hero"><span class="tag"><i></i> %s</span>\n<h1>%s</h1>\n<p class="lead">%s</p>\n<div class="stats">%s</div></header>\n<h2 class="s" id="karya">%s</h2>\n' % (L['tag'], L['h1'], L['lead'], ''.join('<div><b>%s</b><span>%s</span></div>' % s for s in L['stats']), L['sec'])
    for k in ORDER:
        p = P[k]; d = p[lang]
        out += '<section class="proj" style="--c:%s;--c2:%s">%s<div>%s<h3>%s</h3><p>%s</p><div class="chips">%s</div><div class="btns"><a class="b p" href="%s">%s</a><a class="b" href="%s" target="_blank" rel="noopener">%s</a></div></div></section>\n' % (p['c'], p['c2'], frame(k, lang, frm), bdg(k, lang), d['n'], d['s'], chips(p, lang), rel(frm, pdir(lang, k)), L['case'], p['u'], L['visit'])
    out += '<section class="about" id="tentang"><h2>%s</h2><div><p>%s</p><p>%s</p><div class="stack">%s</div></div></section>\n' % (L['about_h'], L['about1'], L['about2'], ''.join('<div class="card"><b>%s</b><span>%s</span></div>' % c for c in L['cards']))
    return out + contact(lang) + '</main>\n' + foot(lang, frm)

def case(lang, key):
    L = T[lang]; p = P[key]; d = p[lang]; frm = pdir(lang, key); h = rel(frm, pdir(lang))
    title = '%s — %s | Kalfin Agus Setiawan' % (d['n'], L['ctitle'])
    out = head(lang, key, title, d['s']) + nav(lang, key)
    out += '<main id="main" class="case" style="--c:%s;--c2:%s"><a class="back" href="%s#karya">%s</a><div class="hero" style="padding-top:26px">%s<h1>%s</h1><p class="lead">%s</p><div class="chips" style="margin-top:18px">%s</div><div class="btns"><a class="b p" href="%s" target="_blank" rel="noopener">%s</a></div></div>' % (p['c'], p['c2'], h, L['back'], bdg(key, lang), d['n'], d['s'], chips(p, lang), p['u'], L['visit'])
    out += frame(key, lang, frm) + '<div class="nums">%s</div>' % ''.join('<div><b>%s</b><span>%s</span></div>' % n for n in d['nums'])
    out += '<div class="cols"><div><h2>%s</h2><p>%s</p></div><div><h2>%s</h2><p>%s</p></div></div>' % (L['prob'], d['p'], L['sol'], d['so'])
    others = ''.join('<a href="%s">%s<small>%s</small></a>' % (rel(frm, pdir(lang, x)), P[x][lang]['n'], P[x][lang]['k']) for x in ORDER if x != key)
    out += '<div class="cols"><div><h2>%s</h2><ul>%s</ul></div><div><h2>%s</h2><div class="more">%s</div></div></div></main>\n' % (L['feat'], ''.join('<li>%s</li>' % x for x in d['f']), L['more'], others)
    return out + foot(lang, frm)

def write(path, txt):
    os.makedirs(os.path.dirname(path) or '.', exist_ok=True); open(path, 'w', encoding='utf-8').write(txt)

urls = []
for lang in ('id', 'en'):
    write(os.path.join(pdir(lang), 'index.html'), home(lang)); urls.append((lang, None))
    for k in ORDER:
        write(os.path.join(pdir(lang, k), 'index.html'), case(lang, k)); urls.append((lang, k))
sm = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'
for lang, k in urls:
    sm += '<url><loc>%s</loc><lastmod>2026-11-06</lastmod><xhtml:link rel="alternate" hreflang="id" href="%s"/><xhtml:link rel="alternate" hreflang="en" href="%s"/><xhtml:link rel="alternate" hreflang="x-default" href="%s"/></url>\n' % (absurl(lang, k), absurl('id', k), absurl('en', k), absurl('id', k))
write('sitemap.xml', sm + '</urlset>\n')
print('Selesai: %d halaman' % len(urls))
